// Korean (Pretendard) subset fonts — generated by tools/gen_kr_fonts.sh.
// These also carry ASCII + the degree sign, so temperatures show "25°".
LV_FONT_DECLARE(font_kr_60);
LV_FONT_DECLARE(font_kr_40);
LV_FONT_DECLARE(font_kr_26);
LV_FONT_DECLARE(font_kr_18);
LV_FONT_DECLARE(font_kr_14);

#define SCR_W  LCD_WIDTH
#define SCR_H  LCD_HEIGHT

// The dog+cat companions live in the top-left corner on every screen (drawn by
// pets.cpp as the topmost siblings). Keep that corner clear of content.
#define PET_RESERVE 92

typedef enum { PANEL_CLOCK = 0, PANEL_INFO, PANEL_STOCK, PANEL_COUNT } panel_screen_t;

static panel_screen_t current = PANEL_CLOCK;
static uint32_t auto_last_ms = 0;
#define AUTO_CYCLE_MS 15000UL

// ---- Clock screen ----
static lv_obj_t* clock_scr = nullptr;
static lv_obj_t* clock_lbl = nullptr;
static lv_obj_t* date_lbl = nullptr;
#define CAL_COLS 7
#define CAL_ROWS 6
static lv_obj_t* cal_cells[CAL_ROWS * CAL_COLS] = {nullptr};
static lv_obj_t* cal_labels[CAL_ROWS * CAL_COLS] = {nullptr};

// ---- Combined weather + air-quality screen ----
