static lv_obj_t* w_temp = nullptr;   // big temperature
static lv_obj_t* w_cond = nullptr;   // condition text
static lv_obj_t* w_feels = nullptr;
static lv_obj_t* w_hum = nullptr;
static lv_obj_t* w_rain = nullptr;
static lv_obj_t* a_value = nullptr;  // big AQI number
static lv_obj_t* a_cat = nullptr;    // AQI category
